    const assignedWordPackIds=canonicalAssignedWordPackId?[canonicalAssignedWordPackId]:(Array.isArray(data.assignedWordPackIds)?data.assignedWordPackIds.filter(Boolean).slice(0,1):[]);
    const assignedWordPackId=assignedWordPackIds[0]||null;
    const assignedQuestionTypes=Array.isArray(data.assignedQuestionTypes)&&data.assignedQuestionTypes.length?data.assignedQuestionTypes:['meaning-choice'];
