    const guildCosmeticEffects=data.guildCosmeticEffects&&typeof data.guildCosmeticEffects==='object'?data.guildCosmeticEffects:{};
    const guildEffects=data.guildEffects&&typeof data.guildEffects==='object'?data.guildEffects:{};
    account={...data,guildCosmetics,guildCosmeticEffects,guildEffects};
    const guildSkinVariantKey=guildCosmetics.equippedVariantKey||null,guildSkinId=guildSkinVariantKey?.split(':')[0]||null,guildSkinRarity=guildSkinVariantKey?.split(':')[1]||null;
    const legacy={...(data.state||{}),name:data.nickname,grade:data.learningGrade,learningGrade:data.learningGrade,activeGuildName:data.activeGuildName||null,activeGuildLogoUrl:data.activeGuildLogoUrl||null,guildSkinVariantKey,guildSkinId,guildSkinRarity,guildCosmeticEffects,guildEffects,freeNicknameChangeUsed:data.freeNicknameChangeUsed,nicknameChangeCount:data.renameCount,isAnonymousStudent:true};
