    Object.assign(gameState,legacy,{uid:window._fbAuth.currentUser.uid,learningGrade:data.learningGrade,isAnonymousStudent:true,activeGuildName:data.activeGuildName||null,activeGuildLogoUrl:data.activeGuildLogoUrl||null,guildSkinVariantKey,guildSkinId,guildSkinRarity,guildCosmeticEffects,guildEffects,assignedWordPackId,assignedWordPackIds,assignedQuestionTypes});
    gameState.guildCosmeticCollectionCount=Array.isArray(guildCosmetics.ownedVariantKeys)?guildCosmetics.ownedVariantKeys.length:0;
