  async function rotateCurrentInvite(){if(!currentInvite)return;const rotate=async()=>{try{const {invite}=await teacherRequest('createInvite',{classId:currentInvite.classId,type:currentInvite.type,rotate:true});await showInvite(invite,currentInvite.type,currentInvite.classId);toast('새 초대 코드·QR·링크를 만들었어요.');}catch(error){alertError(error);}};const message='초대 정보를 갱신하면 지금 보이는 코드·QR·링크는 즉시 사용할 수 없어요.<br><br>새 초대 정보로 바꿀까요?';if(typeof window.showConfirm==='function')window.showConfirm(message,rotate,null,{icon:'🔄',title:'초대 정보 갱신',yesLabel:'새로 만들기',noLabel:'취소'});else rotate();}
  function captureInviteFromLocation(){const hash=location.hash.replace(/^#/,'');if(!hash.includes('='))return;const params=new URLSearchParams(hash);pendingStudentInviteCode=scannedGuildCode(params.get('code'));pendingManagerInviteCode=scannedGuildCode(params.get('managerCode'));if(pendingStudentInviteCode||pendingManagerInviteCode)history.replaceState(null,'',location.pathname+location.search);}
  function openInviteFromLocation(){if(!account||pendingStudentInviteCode.length<6)return;openGuildJoin();showGuildJoinControls();$('secureGuildModalTitle').textContent='초대 링크로 길드 가입';$('secureGuildCode').value=pendingStudentInviteCode;pendingStudentInviteCode='';setTimeout(joinGuild,50);}
  function openManagerInviteFromLocation(){if(pendingManagerInviteCode.length<6)return;openTeacher();$('secureManagerCode').value=pendingManagerInviteCode;if(!$('secureTeacherDashboard').classList.contains('hidden'))switchTeacherTab('create');}
  function clearManagerInvite(){pendingManagerInviteCode='';}
  function scannedGuildCode(value){let raw=String(value||'').trim();try{const url=new URL(raw);const hashParams=new URLSearchParams(url.hash.replace(/^#/,''));raw=url.searchParams.get('code')||url.searchParams.get('managerCode')||hashParams.get('code')||hashParams.get('managerCode')||raw;}catch{}return raw.toUpperCase().replace(/[^A-Z0-9]/g,'');}
  async function joinGuild(){
    try{
      if(!account)throw new Error('먼저 용사를 만든 뒤 길드에 가입할 수 있어요.');
      const code=scannedGuildCode($('secureGuildCode').value);if(code.length<6)throw new Error('길드 초대 코드를 확인해 주세요.');
      const auth=await activeStudentAuth(),{guild}=await request(studentApi,{action:'previewGuildInvite',code},auth);
      const logo=guild.guildLogoUrl?`<img src="${teacherHtml(guild.guildLogoUrl)}" alt="" class="mx-auto mb-3 h-16 w-16 border border-sky-500 object-cover">`:'<div class="mx-auto mb-3 flex h-16 w-16 items-center justify-center border border-sky-500 bg-sky-950/30 text-3xl">🛡️</div>';
      const message=`${logo}<b class="text-lg text-sky-200">${teacherHtml(guild.classLabel)}</b><br><span class="text-sm text-gray-300">현재 길드원 ${Number(guild.memberCount||0).toLocaleString()}명</span><br><br>${guild.alreadyMember?'이미 가입한 길드예요. 다시 연결할까요?':'이 길드에 가입할까요?'}`;
      const execute=async()=>{try{const {membership}=await request(studentApi,{action:'joinClass',code},auth);const classIds=[membership.classId];const updated=await withAssignedWordPack({...account,classIds,activeGuildName:membership.classLabel||account.activeGuildName||null,activeGuildLogoUrl:membership.guildLogoUrl||null});closeGuildJoin();apply(updated);toast(`${membership.classLabel||'길드'}에 가입했어요!`);}catch(error){alertError(error);}};
      if(typeof window.showConfirm==='function')window.showConfirm(message,execute,null,{icon:'🛡️',title:'길드 가입 확인',yesLabel:'이 길드에 가입',noLabel:'취소'});else execute();
    }catch(error){alertError(error);}
  }
