  function renderGuildRankings(rankings){
    const list=$('secureGuildRankList');if(!list)return;list.replaceChildren();
    if(!rankings?.length){list.textContent='아직 순위에 표시할 길드가 없어요.';return;}
    rankings.forEach((entry)=>{
      const row=document.createElement('div'),rank=document.createElement('b'),identity=document.createElement('div'),heading=document.createElement('div'),name=document.createElement('b'),details=document.createElement('span'),score=document.createElement('span'),breakdown=entry.breakdown||{};
      row.className='grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 border-b border-[#282018] bg-[#090909] px-3 py-3';
      rank.className='w-8 text-center text-yellow-300';rank.textContent=entry.rank+'위';identity.className='min-w-0';heading.className='flex min-w-0 items-center gap-2';
      if(entry.guildLogoUrl){const logo=document.createElement('img');logo.src=entry.guildLogoUrl;logo.alt='';logo.loading='lazy';logo.referrerPolicy='no-referrer';logo.className='h-7 w-7 shrink-0 rounded-sm border border-sky-500/60 object-cover';heading.append(logo);}
      name.className='min-w-0 truncate text-white';name.textContent=entry.guildName;heading.append(name);
      details.className='mt-0.5 block truncate text-[9px] text-gray-500';details.textContent=`${Number(entry.memberCount||0).toLocaleString()}명 · 정답 ${Number(breakdown.correct||0).toLocaleString()} · 스테이지 ${Number(breakdown.stage||0).toLocaleString()} · 보스 ${Number(breakdown.worldBoss||0).toLocaleString()} · 시련 ${Number(breakdown.trial||0).toLocaleString()}`;
      score.className='text-right font-black text-sky-300';score.textContent=Number(entry.guildPoints||0).toLocaleString()+'점';identity.append(heading,details);row.append(rank,identity,score);list.append(row);
    });
  }

