  function guildTrialQuestionKey(question){return String(question?.id||question?.word||'').toLowerCase();}
  function normalizeGuildTrialAnswer(value){return String(value||'').normalize('NFKC').trim().toLowerCase().replace(/[^a-z]/g,'');}
  function formatGuildTrialEnglish(value){const raw=String(value||'').normalize('NFKC').trim();if(!/^[A-Za-z]+(?:[ '-][A-Za-z]+)*$/.test(raw))return raw;const lower=raw.toLowerCase(),firstLetterIndex=lower.search(/[a-z]/);return firstLetterIndex<0?lower:lower.slice(0,firstLetterIndex)+lower.charAt(firstLetterIndex).toUpperCase()+lower.slice(firstLetterIndex+1);}
  function formatGuildTrialPrompt(value){const raw=String(value||'문제를 불러오지 못했어요.');return raw.replace(/([“"])([A-Za-z]+(?:[ '-][A-Za-z]+)*)([”"])/g,(_match,open,word,close)=>open+formatGuildTrialEnglish(word)+close);}
