  function applyBossStatus(boss){if(!boss)return boss;if(boss.guardianTitleUnlocked){const titles=Array.from(new Set([...(gameState.unlockedTitles||[]),'수호신']));gameState.unlockedTitles=titles;if(account?.state)account.state.unlockedTitles=titles;if(typeof saveLocalCache==='function')saveLocalCache();window.refreshStateVisuals?.();const noticeKey='vocahero_guardian_title_notice_'+String(boss.week||'');if(!localStorage.getItem(noticeKey)){localStorage.setItem(noticeKey,'1');toast('👑 월드보스 기여 1위! [수호신] 칭호를 즉시 획득했습니다.');}}window._applySecureWorldBossStatus?.(boss);return boss;}
