  async function secureWorldBossWeeklyReward(){
    if(weeklyRewardChecked)return null;
    weeklyRewardChecked=true;
    let reward;
    try{({reward}=await request(worldBossApi,{action:'weeklyReward'},window._fbAuth));}
    catch(error){weeklyRewardChecked=false;throw error;}
    if(!reward?.participated||reward.alreadyClaimed)return reward;
    gameState.masteryPoints=Number(gameState.masteryPoints||0)+Number(reward.rewardFp||0);
    if(account?.state)account.state.masteryPoints=gameState.masteryPoints;
    if(reward.gotTitle){
      gameState.unlockedTitles=Array.from(new Set([...(gameState.unlockedTitles||[]),'수호신']));
      if(account?.state)account.state.unlockedTitles=gameState.unlockedTitles;
    }
    if(typeof saveLocalCache==='function')saveLocalCache();
    window.refreshStateVisuals?.();
    const modal=$('wbVictoryNoticeModal');
    const resultText=reward.defeated?'완전 승리':'토벌 실패 · 부분 보상';
    if(modal){
      const heading=modal.querySelector('h2'),description=$('wbModalDescription'),banner=$('wbModalBanner'),status=$('wbModalClearStatus'),damage=$('wbModalMyDamage'),share=$('wbModalMyShare'),rank=$('wbModalMyRank'),summary=$('wbModalRewardSummary'),claim=$('wbVictoryNoticeClaimBtn');
      if(banner)banner.textContent=reward.defeated?'월드보스 주간 결산 · 전 학년 연합 토벌 성공':'월드보스 주간 결산 · 다음 토벌을 준비하세요';
      if(heading)heading.textContent=reward.defeated?'🏆 월드보스 완전 토벌!':'⚔️ 월드보스 주간 전투 종료';
      if(description)description.textContent=`지난 주 전 학년 용사들이 총 ${Number(reward.totalDamage||0).toLocaleString()} 피해를 기록했어요.`;
      if(status){status.textContent=resultText+(reward.defeated?' ✅':'');status.style.color=reward.defeated?'#4ade80':'#f87171';}
      if(damage)damage.textContent=Number(reward.myDamage||0).toLocaleString()+' HP';
      if(share)share.textContent=(Number(reward.teamContributionRate||0)*100).toFixed(2)+'%';
      if(rank)rank.textContent=reward.myRank?`${Number(reward.myRank).toLocaleString()}위 / ${Number(reward.participantCount||0).toLocaleString()}명`:'집계되지 않음';
      if(summary)summary.textContent=`+${Number(reward.rewardFp||0).toLocaleString()} FP${reward.gotTitle?' · [수호신] 칭호 획득':''}`;
      if(claim)claim.onclick=()=>{window.closeModal?.('wbVictoryNoticeModal');toast(`월드보스 주간 보상 +${Number(reward.rewardFp||0).toLocaleString()} FP를 확인했어요.`);};
      window.openModal?.('wbVictoryNoticeModal');
      window.playSoundEffect?.('levelup');
    }else{
      const titleText=reward.gotTitle?'<br><b class="text-yellow-300">누적 피해 1위로 [수호신] 칭호를 획득했어요!</b>':'';
      window.showAlert?.(`지난 주 월드보스 결산: ${resultText}<br>기여율 ${(Number(reward.teamContributionRate||0)*100).toFixed(2)}% · ${reward.myRank||'-'}위<br><b>+${Number(reward.rewardFp||0).toLocaleString()} FP</b>${titleText}`,'🏆','월드보스 주간 결산');
    }
    return reward;
  }
  async function secureWorldBossRaidStatus(damage=null,correctAnswers=null){const raid=readBossRaid(),hasCheckpoint=raid&&Number.isFinite(Number(damage))&&Number.isFinite(Number(correctAnswers)),payload=hasCheckpoint?{action:'checkpoint',raidToken:raid.token,damage:Math.max(0,Math.floor(Number(damage)||0)),correctAnswers:Math.max(0,Math.floor(Number(correctAnswers)||0))}:{action:'raidStatus'};const {boss}=await request(worldBossApi,payload,window._fbAuth);window._applySecureWorldBossRaidHp?.(boss);return boss;}
